// logo.ts - the animated freva brand mark (64px animated WebP, ~80KB, displayed at 45px).
//
// Delivered as a base64 data URI so it ships in the bundle with NO extra network request, and shown
// via a plain <img>: the browser decodes it once and animates it on the compositor (negligible CPU,
// and throttled automatically when the tab is hidden). The FULL 120-frame sequence is kept at its
// original 80ms/frame (12.5fps) so the motion stays smooth; bytes are held down by size + quality,
// not by dropping frames - dropping frames is what makes the motion look choppy.
export const LOGO_DATA_URI: string =
  "data:image/webp;base64,";
